// Monta o prompt (system + user) para o plano estrategico do mes.
// Le o payload C5 do Webhook e devolve os campos usados pelos nos de LLM e callback.
// A API key vem NO PAYLOAD (body.ai.apiKey), resolvida server-side pelo Go a partir do
// banco (contrato PAY, wave 3). Os nos HTTP usam essa key — sem credential/$env no n8n;
// a key crua nunca e logada nem persistida aqui.
const body = ($('Webhook').first().json.body) || {};
const ai = body.ai || {};
const clients = Array.isArray(body.clients) ? body.clients : [];
const holidays = Array.isArray(body.holidays) ? body.holidays : [];
// Base URLs default por provider (espelha C2 do Omni). Vazio na config = usa o default.
const DEFAULT_BASE = {
  claude: 'https://api.anthropic.com',
  openai: 'https://api.openai.com/v1',
  gemini: 'https://generativelanguage.googleapis.com/v1beta/openai',
  glm: 'https://api.z.ai/api/paas/v4',
  deepseek: 'https://api.deepseek.com',
  qwen: 'https://dashscope.aliyuncs.com/compatible-mode/v1',
  kimi: 'https://api.moonshot.cn/v1'
};
const provider = String(ai.provider || 'claude').toLowerCase();
// A API key vem no payload (body.ai.apiKey), resolvida server-side pelo Go a partir do banco.
const apiKey = String(ai.apiKey || '');
const model = ai.model || 'claude-sonnet-5';
const baseUrl = String(ai.baseUrl || DEFAULT_BASE[provider] || '').replace(/\/+$/, '');
let temperature = Number(ai.temperature);
if (isNaN(temperature)) temperature = 0.7;
if (temperature < 0) temperature = 0;
if (temperature > 1) temperature = 1;
// System prompt: usa o da config OU o DEFAULT (estrategia de conteudo pt-BR, saida JSON estrito).
const DEFAULT_SYSTEM = [
  'Voce e um estrategista de conteudo para redes sociais de uma agencia brasileira.',
  'Monte um plano estrategico do mes por cliente, em pt-BR, com base no perfil de cada cliente,',
  'nas datas comemorativas/feriados do mes e nas notas do mes.',
  'Responda SOMENTE com um objeto JSON valido (sem markdown, sem cercas de codigo, sem comentarios),',
  'exatamente neste shape:',
  '{',
  '  "summary": "resumo geral do plano",',
  '  "pillars": [{ "name": "pilar", "proportion": "ex: 40%", "rationale": "por que" }],',
  '  "clients": [{',
  '    "clientId": "id recebido", "clientName": "nome recebido", "strategy": "estrategia do cliente",',
  '    "days": [{ "date": "YYYY-MM-DD", "type": "post|story|reels", "idea": "ideia", "copy": "rascunho de copy" }]',
  '  }]',
  '}',
  'Use apenas os clientId e clientName recebidos. Datas sempre dentro do mes informado.',
  'Nao invente dados que nao estejam no perfil; quando faltar, seja generico e seguro.'
].join('\n');
const system = (ai.systemPrompt && String(ai.systemPrompt).trim()) ? String(ai.systemPrompt) : DEFAULT_SYSTEM;
// Monta a parte do usuario com mes, feriados, clientes/perfis e notas.
const NL = String.fromCharCode(10);
let user = 'Mes alvo: ' + (body.month || '') + NL;
user += 'Idioma: ' + (body.language || 'pt-BR') + NL + NL;
if (holidays.length) {
  user += 'Datas comemorativas / feriados do mes:' + NL;
  for (const h of holidays) {
    user += '- ' + (h.date || '') + ': ' + (h.name || '') + ' (' + (h.set || '') + ')' + NL;
  }
  user += NL;
} else {
  user += 'Sem feriados cadastrados para este mes.' + NL + NL;
}
user += 'Clientes e perfis:' + NL;
for (const c of clients) {
  user += '### ' + (c.name || '') + ' (id: ' + (c.id || '') + ')' + NL;
  user += 'Perfil: ' + JSON.stringify(c.profile || {}) + NL + NL;
}
const monthNotes = body.monthNotes || '';
if (monthNotes) {
  user += 'Notas do mes (HTML, use como contexto):' + NL + monthNotes + NL;
}
return [{ json: {
  planId: body.planId || '',
  month: body.month || '',
  provider: provider,
  model: model,
  baseUrl: baseUrl,
  apiKey: apiKey,
  temperature: temperature,
  system: system,
  user: user,
  callbackUrl: body.callbackUrl || '',
  serviceToken: body.serviceToken || ''
} }];

// Normaliza a resposta do LLM (anthropic vs openai-compat), remove cercas de codigo
// e faz JSON.parse com try/catch. Devolve { status:'done', content } ou { status:'error', error }.
const prompt = $('Montar prompt').first().json;
const planId = prompt.planId;
const provider = prompt.provider;
const r = $input.first().json || {};
// Item de erro do HTTP node (continueRegularOutput): tem a chave 'error'.
if (r.error && !r.content && !r.choices) {
  const emsg = (r.error && (r.error.message || r.error.description)) || 'LLM request failed';
  return [{ json: { planId: planId, status: 'error', content: {}, error: String(emsg), callbackUrl: prompt.callbackUrl, serviceToken: prompt.serviceToken } }];
}
let text = '';
if (provider === 'claude') {
  // Anthropic: content e um array de blocos; pega o primeiro bloco de texto.
  const blocks = Array.isArray(r.content) ? r.content : [];
  const first = blocks.find(function (b) { return b && b.type === 'text'; }) || blocks[0] || {};
  text = String(first.text || '');
} else {
  // OpenAI-compat: choices[0].message.content.
  const choices = Array.isArray(r.choices) ? r.choices : [];
  const msg = (choices[0] || {}).message || {};
  text = String(msg.content || '');
}
text = text.trim();
// Remove cercas de codigo (```json ... ``` ou ``` ... ```).
if (text.indexOf('```') !== -1) {
  text = text.replace(/^```[a-zA-Z]*[ \t]*[\r\n]?/, '').replace(/```\s*$/, '').trim();
}
// Se ainda houver texto antes/depois do JSON, tenta recortar do primeiro { ao ultimo }.
if (text.charAt(0) !== '{') {
  const start = text.indexOf('{');
  const end = text.lastIndexOf('}');
  if (start !== -1 && end !== -1 && end > start) text = text.slice(start, end + 1);
}
try {
  const content = JSON.parse(text);
  return [{ json: { planId: planId, status: 'done', content: content, error: '', callbackUrl: prompt.callbackUrl, serviceToken: prompt.serviceToken } }];
} catch (e) {
  return [{ json: { planId: planId, status: 'error', content: {}, error: 'invalid_json_from_llm: ' + String((e && e.message) || e), callbackUrl: prompt.callbackUrl, serviceToken: prompt.serviceToken } }];
}
